using System;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.EventSystems;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class ExtraUpgradeEdgeCheck{
static BokumyakuGame g;static BokumyakuBattleHud hud;static MethodInfo refresh;static int phase,frame;static List<object> rows;static GameObject panel;
public static object Run(){g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");hud=UnityEngine.Object.FindFirstObjectByType<BokumyakuBattleHud>();refresh=typeof(BokumyakuBattleHud).GetMethod("Refresh",BindingFlags.Instance|BindingFlags.NonPublic);panel=(GameObject)typeof(BokumyakuBattleHud).GetField("extraPanel",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(hud);rows=new List<object>();phase=0;frame=Time.frameCount;EditorApplication.update+=Poll;return "Six rendered-frame UI edge checks";}
static void Poll(){if(Time.frameCount==frame)return;frame=Time.frameCount;try{switch(phase++){
case 0:Click("ExtraUpgrades");break;
case 1:var levels=(int[])typeof(RunSimulator).GetField("levels",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(g.Run);typeof(RunSimulator).GetProperty("RunInk").SetValue(g.Run,50000);for(int i=5;i<7;i++)levels[i]=g.Run.UpgradeMaxLevel((UpgradeKind)i);refresh.Invoke(hud,null);for(int i=5;i<7;i++){int before=g.Run.RunInk;Click(i==5?"UpgradeBleed":"UpgradeHarvest");rows.Add(new{name="cap "+i,passed=g.Run.RunInk==before&&g.Run.UpgradeLevels[i]==g.Run.UpgradeMaxLevel((UpgradeKind)i)});}Click("ExtraUpgrades");rows.Add(new{name="close",passed=!panel.activeSelf});break;
case 2:Click("ExtraUpgrades");rows.Add(new{name="reopen",passed=panel.activeSelf});break;
case 3:int seed=g.Run.Seed;if(!g.AbandonRun()||!g.TryStartRun(seed))throw new Exception("Restart failed");g.SetPaused(true);refresh.Invoke(hud,null);rows.Add(new{name="same seed restart closes",passed=!panel.activeSelf});break;
case 4:Click("ExtraUpgrades");Click("Home");break;
case 5:rows.Add(new{name="home closes",passed=!panel.activeSelf});g.SetPage(BokumyakuGame.GamePage.Battle);EditorApplication.update-=Poll;File.WriteAllText(Path.GetFullPath("../docs/evidence/extra-upgrade-edges.json"),Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));break;}}catch(Exception e){EditorApplication.update-=Poll;File.WriteAllText(Path.GetFullPath("../docs/evidence/extra-upgrade-edges.json"),e.ToString());throw;}}
static void Click(string name){var b=GameObject.Find(name).GetComponent<UnityEngine.UI.Button>();var r=(RectTransform)b.transform;var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);if(hits.Count==0||hits[0].gameObject.GetComponentInParent<UnityEngine.UI.Button>()!=b)throw new Exception("Blocked "+name);ExecuteEvents.Execute(b.gameObject,d,ExecuteEvents.pointerClickHandler);}}
